// GENERATED from mexplore_import/src/convert.js — do not edit; run `node scripts/sync-vendored.mjs`
/**
 * Claude Code session history -> mexplor-unit-v1 units, ported from a reference importer
 * `history_import/convert.py` (the reference implementation; parity is checked against goldens it
 * generated, test/fixtures/history/golden.json, and a synthetic export with matching unit ids).
 *
 * Pipeline: read every top-level session file once -> drop non-conversation entries -> dedupe entries
 * by uuid across files (resumed/forked sessions copy history) -> build turns (one real user message +
 * the assistant's final text before the next real user message) -> segment per session x local day x
 * idle gap -> carry short segments forward -> render with the assistant cap stages and split at turn
 * boundaries until each unit fits -> redact -> sort globally by start time.
 *
 * Python-compatibility rules kept on purpose: lengths and caps count code points (Python `len`), not
 * UTF-16 units; times are rendered in Asia/Shanghai (fixed +08:00) exactly like `datetime.isoformat()`,
 * so `unit_id` (sha256 of "session|start") matches the Python units byte for byte.
 *
 * @module mexplore-import/convert
 */

import { createHash } from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'

import { expandHome, loadEnvFiles, Redactor } from './redact.js'

export const SCHEMA = 'mexplor-unit-v1'
export const TRUNCATION_MARKER = ' …[truncated]'
const OFFSET_MS = 8 * 3600 * 1000 // Asia/Shanghai, no DST since 1991

export const DEFAULTS = Object.freeze({
  idleGapHours: 2,
  minUnitChars: 300,
  assistantCap: 2000,
  assistantCapTight: 667,
  userCap: 4000,
  maxEvidence: 50,
  runConfigBudget: 60000,
})

const NOISE_PREFIXES = [
  '<task-notification>',
  '<local-command-stdout>',
  '<local-command-stderr>',
  '<local-command-caveat>',
  '<bash-input>',
  '<bash-stdout>',
  '<bash-stderr>',
  '<user-prompt-submit-hook>',
  'Caveat: The messages below were generated by the user while running local commands',
  '[Request interrupted by user',
  'This session is being continued from a previous conversation',
]
const NOISE_ORIGINS = new Set(['task-notification', 'peer'])
const SYSTEM_REMINDER = /<system-reminder>[\s\S]*?<\/system-reminder>/g
const COMMAND_NAME = /<command-name>\s*(\/?[^<\s]+)\s*<\/command-name>/
const COMMAND_ARGS = /<command-args>([\s\S]*?)<\/command-args>/

// ---------------------------------------------------------------- code points and time

/** Python len(): code points. */
export function cpLen(s) {
  let n = s.length
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i)
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1)
      if (d >= 0xdc00 && d <= 0xdfff) {
        n -= 1
        i += 1
      }
    }
  }
  return n
}

/** Python s[:n] on code points. */
export function cpSlice(s, n) {
  if (s.length <= n) return s
  let i = 0
  let count = 0
  while (i < s.length && count < n) {
    const c = s.charCodeAt(i)
    i += c >= 0xd800 && c <= 0xdbff && i + 1 < s.length && s.charCodeAt(i + 1) >= 0xdc00 && s.charCodeAt(i + 1) <= 0xdfff ? 2 : 1
    count += 1
  }
  return s.slice(0, i)
}

/** Python str.strip() for the whitespace that matters here. */
const pyStrip = (s) => s.replace(/^[\s\x1c-\x1f\x85]+|[\s\x1c-\x1f\x85]+$/gu, '')

export function parseTs(s) {
  return Date.parse(s) / 1000
}

const pad = (n, w = 2) => String(n).padStart(w, '0')

/** datetime.fromtimestamp(t, Asia/Shanghai).isoformat() (microseconds only when non-zero). */
export function iso(t) {
  const ms = Math.round(t * 1000)
  const d = new Date(ms + OFFSET_MS)
  const base = `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}T${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`
  const micro = (((ms % 1000) + 1000) % 1000) * 1000
  return `${base}${micro ? `.${pad(micro, 6)}` : ''}+08:00`
}

export function localDay(t) {
  return iso(t).slice(0, 10)
}

export function dayEnd(day) {
  return (Date.parse(`${day}T00:00:00+08:00`) + 86400000) / 1000
}

// ---------------------------------------------------------------- reading

/** Top-level <project>/<session>.jsonl only; subagent transcripts live in <session>/subagents/. */
export function sessionFiles(projectsDir, excludePrefixes = [], onlyProjects = null) {
  const root = expandHome(projectsDir)
  const out = []
  let names
  try {
    names = fs.readdirSync(root).sort()
  } catch {
    return out
  }
  for (const name of names) {
    const dir = path.join(root, name)
    if (!fs.statSync(dir).isDirectory() || excludePrefixes.some((p) => name.startsWith(p))) continue
    if (onlyProjects && !onlyProjects.has(name)) continue
    for (const f of fs.readdirSync(dir).filter((x) => x.endsWith('.jsonl')).sort()) {
      if (fs.statSync(path.join(dir, f)).isFile()) out.push(path.join(dir, f))
    }
  }
  return out
}

function readEntries(file, counts) {
  const entries = []
  const text = fs.readFileSync(file, 'utf8')
  for (const line of text.split('\n')) {
    if (!line.trim()) continue
    let d
    try {
      d = JSON.parse(line)
    } catch {
      bump(counts, 'bad_json_lines')
      continue
    }
    if (!d || (d.type !== 'user' && d.type !== 'assistant') || !d.uuid || !d.timestamp) continue
    entries.push(d)
  }
  return entries
}

const bump = (counts, key, n = 1) => {
  counts[key] = (counts[key] ?? 0) + n
}

/** [text, media kinds, kind]; kind: 'human' | 'tool_result' | 'noise:<why>' | 'empty'. */
export function userText(entry) {
  if (entry.isSidechain) return ['', [], 'noise:sidechain']
  if (entry.isMeta) return ['', [], 'noise:meta']
  if (entry.isCompactSummary) return ['', [], 'noise:compact_summary']
  if (entry.isVisibleInTranscriptOnly) return ['', [], 'noise:transcript_only']
  const origin = entry.origin ?? {}
  if (NOISE_ORIGINS.has(origin.kind)) return ['', [], `noise:origin_${origin.kind}`]
  const content = entry.message?.content
  const media = []
  let text
  if (typeof content === 'string') {
    text = content
  } else {
    const parts = []
    let hasToolResult = false
    for (const block of content ?? []) {
      if (!block || typeof block !== 'object' || Array.isArray(block)) continue
      const kind = block.type
      if (kind === 'text') parts.push(String(block.text ?? ''))
      else if (kind === 'tool_result') hasToolResult = true
      else media.push(kind || 'unknown')
    }
    if (hasToolResult && parts.length === 0) return ['', [], 'tool_result']
    text = parts.join('\n')
  }
  text = pyStrip(text.replace(SYSTEM_REMINDER, ''))
  if (NOISE_PREFIXES.some((p) => text.startsWith(p))) return ['', [], 'noise:wrapper']
  if (text.includes('<command-name>')) {
    const name = COMMAND_NAME.exec(text)
    const args = COMMAND_ARGS.exec(text)
    const argsText = args ? pyStrip(args[1]) : ''
    if (!name || !argsText) return ['', [], 'noise:slash_command']
    text = `${name[1]} ${argsText}`
  }
  if (!text && media.length === 0) return ['', [], 'empty']
  return [text, media, 'human']
}

function assistantBlocks(entry) {
  if (entry.isSidechain) return []
  const content = entry.message?.content
  if (typeof content === 'string') return [content]
  return (content ?? []).filter((b) => b && typeof b === 'object' && b.type === 'text').map((b) => String(b.text ?? ''))
}

/** All turns, deduplicated by entry uuid across files. */
export function loadTurns(cfg, counts, files = null) {
  files = files ?? sessionFiles(cfg.projectsDir, cfg.excludeProjectPrefixes ?? [])
  counts.session_files = files.length
  const loaded = []
  for (const file of files) {
    const entries = readEntries(file, counts)
    if (entries.length) loaded.push([entries.reduce((m, e) => Math.min(m, parseTs(e.timestamp)), Infinity), file, entries])
  }
  loaded.sort((a, b) => a[0] - b[0] || (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0))
  const seen = new Set()
  const turns = []
  const gap = cfg.idleGapHours * 3600
  for (const [, file, entries] of loaded) {
    entries.sort((a, b) => parseTs(a.timestamp) - parseTs(b.timestamp))
    let current = null
    for (const e of entries) {
      if (seen.has(e.uuid)) {
        bump(counts, 'duplicate_entries_skipped')
        continue
      }
      seen.add(e.uuid)
      const ts = parseTs(e.timestamp)
      if (current !== null && ts - current._end_ts >= gap) {
        bump(counts, 'turns_detached_after_idle_gap')
        current = null
      }
      if (e.type === 'user') {
        const [text, media, kind] = userText(e)
        if (kind === 'human') {
          bump(counts, 'human_turns')
          current = {
            turn_id: e.uuid,
            session_id: e.sessionId || path.basename(file, '.jsonl'),
            cwd: e.cwd || '',
            entrypoint: e.entrypoint || 'unknown',
            user: text,
            media,
            _ts: ts,
            _end_ts: ts,
            _assistant: [],
          }
          turns.push(current)
          continue
        }
        bump(counts, `user_entries_${kind.replace(':', '_')}`)
      } else if (e.type === 'assistant') {
        if (current === null) continue
        const blocks = assistantBlocks(e).filter((b) => pyStrip(b))
        if (blocks.length) current._assistant.push([e.message?.id || e.uuid, blocks.join('\n')])
      }
      if (current !== null && (e.sessionId ?? current.session_id) === current.session_id) {
        current._end_ts = Math.max(current._end_ts, ts)
      }
    }
  }
  for (const t of turns) {
    t.assistant = finalReply(t._assistant)
    delete t._assistant
  }
  return turns
}

function finalReply(chunks) {
  if (!chunks.length) return ''
  const lastId = chunks[chunks.length - 1][0]
  return chunks.filter(([id]) => id === lastId).map(([, text]) => text).join('\n')
}

// ---------------------------------------------------------------- rendering

/** Cap at `cap` code points; never cut through a redaction marker. */
export function clip(text, cap) {
  if (cpLen(text) <= cap) return text
  text = cpSlice(text, cap)
  if (text.lastIndexOf('[REDACTED:') > text.lastIndexOf(']')) text = text.slice(0, text.lastIndexOf('[REDACTED:'))
  return text + TRUNCATION_MARKER
}

function userBody(turn, cfg) {
  let text = turn.user_redacted
  for (const kind of turn.media) text += `\n[media:${kind}]`
  return clip(text, cfg.userCap)
}

function render(turns, header, acap, cfg) {
  const lines = [header]
  for (const t of turns) {
    lines.push(`USER: ${userBody(t, cfg)}`)
    if (pyStrip(t.assistant_redacted)) lines.push(`ASSISTANT: ${clip(t.assistant_redacted, acap)}`)
  }
  return lines.join('\n')
}

export function header(day, sid, cwd, ordinal, i = 1, m = 1) {
  const base = `Conversation dated ${day} (Claude Code session ${sid} in ${cwd}, part ${ordinal} of that session`
  return base + (m === 1 ? ')' : `, part ${i}/${m} of that day)`)
}

/** (evidence entries, run-config bytes estimate) for the delegation built from `text` (convert.delegation_size). */
export function delegationSize(text, day) {
  const lines = text.split('\n')
  const entries = []
  for (const line of lines.slice(1)) {
    if (line.startsWith('USER: ') || line.startsWith('ASSISTANT: ')) entries.push([line.slice(line.indexOf(': ') + 2)])
    else if (entries.length) entries[entries.length - 1].push(line)
  }
  const evidence = entries.map((e) => ({ sourceId: 'x'.repeat(40), role: 'assistant', sourceKind: 'conversation', content: e.join('\n'), complete: false, date: day }))
  const blob = JSON.stringify({ message: 'm'.repeat(cpLen(lines[0]) + 220), evidence })
  return [entries.length, Buffer.byteLength(blob, 'utf8') + 1500]
}

function fits(text, day, cfg) {
  const [n, size] = delegationSize(text, day)
  return n <= cfg.maxEvidence && size <= cfg.runConfigBudget
}

function planParts(turns, headerFor, day, cfg) {
  for (const [stage, acap] of [['full', cfg.assistantCap], [`assistant_${cfg.assistantCapTight}`, cfg.assistantCapTight]]) {
    const text = render(turns, headerFor(1, 1), acap, cfg)
    if (fits(text, day, cfg)) return [[turns, text, stage]]
  }
  const acap = cfg.assistantCapTight
  const chunks = []
  let cur = []
  for (const t of turns) {
    if (cur.length && !fits(render([...cur, t], headerFor(9, 9), acap, cfg), day, cfg)) {
      chunks.push(cur)
      cur = []
    }
    cur.push(t)
  }
  chunks.push(cur)
  return chunks.map((c, i) => [c, render(c, headerFor(i + 1, chunks.length), acap, cfg), `assistant_${acap}+split`])
}

function unitChars(turns, cfg) {
  const t = turns[0]
  return cpLen(render(turns, header(localDay(t._ts), t.session_id, t.cwd, 1), cfg.assistantCap, cfg))
}

// ---------------------------------------------------------------- segmentation

const cmpStr = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

/** Session x local day x idle segment; short segments carried forward, dropped at day end. */
export function plan(turns, cfg, now) {
  const gap = cfg.idleGapHours * 3600
  const byKey = new Map()
  for (const t of turns) {
    const key = `${t.session_id}\u0000${localDay(t._ts)}`
    if (!byKey.has(key)) byKey.set(key, [])
    byKey.get(key).push(t)
  }
  const ordered = [...byKey.entries()].map(([k, ts]) => [k.split('\u0000'), ts, ts[0]._ts])
  ordered.sort((a, b) => a[2] - b[2] || cmpStr(a[0][0], b[0][0]) || cmpStr(a[0][1], b[0][1]))
  const decided = new Map()
  const stats = {}
  const push = (sid, v) => {
    if (!decided.has(sid)) decided.set(sid, [])
    decided.get(sid).push(v)
  }
  for (const [[sid, day], ts] of ordered) {
    ts.sort((a, b) => a._ts - b._ts || cmpStr(a.turn_id, b.turn_id))
    const segments = []
    let cur = [ts[0]]
    let segEnd = ts[0]._end_ts
    for (const t of ts.slice(1)) {
      if (t._ts - segEnd >= gap) {
        segments.push(cur)
        cur = []
      }
      cur.push(t)
      segEnd = Math.max(segEnd, t._end_ts)
    }
    segments.push(cur)
    bump(stats, 'segments', segments.length)
    let carry = []
    let carryN = 0
    for (const seg of segments) {
      const closedAt = Math.max(...seg.map((t) => t._end_ts)) + gap
      if (closedAt > now) {
        bump(stats, 'segments_still_open')
        carry = null
        break
      }
      const group = [...carry, ...seg]
      if (unitChars(group, cfg) < cfg.minUnitChars) {
        carry = group
        carryN += 1
        continue
      }
      if (carryN) bump(stats, 'short_segments_merged', carryN)
      push(sid, ['emit', group, closedAt])
      carry = []
      carryN = 0
    }
    if (carry && carry.length && now >= Math.max(dayEnd(day), Math.max(...carry.map((t) => t._end_ts)) + gap)) {
      bump(stats, 'short_segments_dropped', carryN)
      bump(stats, 'turns_dropped_short', carry.length)
      push(sid, ['drop', carry, null])
    }
  }
  return [decided, stats]
}

export function unitId(sessionId, startTs) {
  return `u-${createHash('sha256').update(`${sessionId}|${iso(startTs)}`).digest('hex').slice(0, 24)}`
}

function addCounts(counts, prefix, found) {
  for (const [k, v] of Object.entries(found)) bump(counts, `${prefix}:${k}`, v)
}

export function redactTurns(turns, redactor, counts) {
  for (const t of turns) {
    const [u, a] = redactor.redact(t.user)
    const [b, c] = redactor.redact(t.assistant)
    t.user_redacted = u
    t.assistant_redacted = b
    addCounts(counts, 'message', a)
    addCounts(counts, 'message', c)
  }
}

export function buildUnits(decided, cfg, redactor, counts) {
  const units = []
  for (const [sid, groups] of decided) {
    let ordinal = 0
    for (const [kind, group, closedAt] of groups) {
      if (kind === 'drop') continue
      ordinal += 1
      const day = localDay(group[0]._ts)
      const cwd = group[0].cwd
      const ord = ordinal
      const headerFor = (i, m) => header(day, sid, cwd, ord, i, m)
      const parts = planParts(group, headerFor, day, cfg)
      parts.forEach(([chunk, rendered, stage], idx) => {
        const [text, found] = redactor.redact(rendered)
        addCounts(counts, 'render', found)
        const [entries, size] = delegationSize(text, day)
        const start = chunk[0]._ts
        units.push({
          unit_id: unitId(sid, start),
          session_id: sid,
          source: `claude-code:${chunk[0].entrypoint}`,
          started_at: iso(start),
          ended_at: iso(Math.max(...chunk.map((t) => t._end_ts))),
          day,
          part: idx + 1,
          parts: parts.length,
          cap_stage: stage,
          turn_ids: chunk.map((t) => t.turn_id),
          text,
          schema: SCHEMA,
          _closed_at: closedAt,
          _start_ts: start,
          _entries: entries,
          _run_config_bytes: size,
        })
      })
    }
  }
  units.sort((a, b) => Math.round(a._start_ts * 1e6) - Math.round(b._start_ts * 1e6) || cmpStr(a.unit_id, b.unit_id))
  return units
}

/** Full conversion: {units, counts, turns}. `files` restricts to a selected list of session files. */
export function convert(cfg, now, files = null) {
  const c = { ...DEFAULTS, ...cfg }
  const counts = {}
  const turns = loadTurns(c, counts, files)
  const [names, values] = loadEnvFiles(c.envFiles ?? [])
  // Secrets the host holds in memory (design §2.6); never written anywhere.
  for (const v of c.secretValues ?? []) if (typeof v === 'string' && [...v].length >= 8) values.push(['HOST_SECRET', v])
  counts.env_names_loaded = names.length
  counts.exact_values_loaded = values.length
  const redactor = new Redactor(names, values)
  redactTurns(turns, redactor, counts)
  const [decided, stats] = plan(turns, c, now)
  for (const [k, v] of Object.entries(stats)) bump(counts, k, v)
  const units = buildUnits(decided, c, redactor, counts)
  return { units, counts, turns }
}
